-- 093_payment_certification_evidence.sql
-- Roadmap G.38: immutable evidence snapshot before any certification decision.
CREATE TABLE IF NOT EXISTS public.project_payment_certification_cases(
 id uuid PRIMARY KEY,project_id bigint NOT NULL REFERENCES public.projects(id)ON DELETE RESTRICT,milestone_id uuid NOT NULL REFERENCES public.project_payment_milestones(id)ON DELETE RESTRICT,case_number integer NOT NULL CHECK(case_number>0),status text NOT NULL CHECK(status IN('UNDER_CERTIFICATION','APPROVED','PARTIALLY_APPROVED','HELD','SENT_FOR_PAYMENT','PAID')),opened_by uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,opened_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,case_number),UNIQUE(milestone_id)
);
CREATE TABLE IF NOT EXISTS public.project_payment_certification_evidence(
 certification_case_id uuid PRIMARY KEY REFERENCES public.project_payment_certification_cases(id)ON DELETE RESTRICT,project_id bigint NOT NULL,milestone_id uuid NOT NULL,contract_milestone_amount numeric(24,2)NOT NULL CHECK(contract_milestone_amount>=0),required_progress numeric(8,4)NOT NULL CHECK(required_progress>=0 AND required_progress<=100),contractor_reported_progress numeric(8,4),pm_verified_progress numeric(8,4),pm_verified_at date,schedule_progress numeric(8,4),boq_quantity_progress numeric(8,4),boq_quantity_evidence_available boolean NOT NULL,open_critical_issue_count integer NOT NULL CHECK(open_critical_issue_count>=0),open_snag_count integer NOT NULL CHECK(open_snag_count>=0),pending_variation_count integer NOT NULL CHECK(pending_variation_count>=0),pending_variation_exposure numeric(24,2)NOT NULL CHECK(pending_variation_exposure>=0),documents jsonb NOT NULL CHECK(jsonb_typeof(documents)='array'),evidence_note text NOT NULL CHECK(char_length(evidence_note)<=3000),evidence_ready boolean NOT NULL,captured_by uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,captured_at timestamptz NOT NULL DEFAULT now()
);
CREATE OR REPLACE FUNCTION private.prevent_payment_evidence_mutation()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN RAISE EXCEPTION'PAYMENT_CERTIFICATION_EVIDENCE_IMMUTABLE'USING ERRCODE='55000';END;$$;DROP TRIGGER IF EXISTS payment_certification_evidence_immutable ON public.project_payment_certification_evidence;CREATE TRIGGER payment_certification_evidence_immutable BEFORE UPDATE OR DELETE ON public.project_payment_certification_evidence FOR EACH ROW EXECUTE FUNCTION private.prevent_payment_evidence_mutation();
ALTER TABLE public.project_payment_certification_cases ENABLE ROW LEVEL SECURITY;ALTER TABLE public.project_payment_certification_evidence ENABLE ROW LEVEL SECURITY;DROP POLICY IF EXISTS payment_certification_cases_select ON public.project_payment_certification_cases;DROP POLICY IF EXISTS payment_certification_evidence_select ON public.project_payment_certification_evidence;CREATE POLICY payment_certification_cases_select ON public.project_payment_certification_cases FOR SELECT TO authenticated USING(public.can_access_project(project_id));CREATE POLICY payment_certification_evidence_select ON public.project_payment_certification_evidence FOR SELECT TO authenticated USING(public.can_access_project(project_id));REVOKE ALL ON TABLE public.project_payment_certification_cases,public.project_payment_certification_evidence FROM PUBLIC,anon,authenticated,service_role;GRANT SELECT ON TABLE public.project_payment_certification_cases,public.project_payment_certification_evidence TO authenticated;

CREATE OR REPLACE FUNCTION public.get_project_payment_certifications(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$BEGIN IF auth.uid()IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PAYMENT_CERTIFICATION_FORBIDDEN'USING ERRCODE='42501';END IF;RETURN jsonb_build_object('projectId',p_project_id,'cases',COALESCE((SELECT jsonb_agg(jsonb_build_object('certificationCaseId',c.id,'caseNumber',c.case_number,'status',c.status,'milestoneId',c.milestone_id,'milestoneTitle',m.title,'plannedAmount',m.planned_amount,'currencyCode',s.currency_code,'openedAt',c.opened_at,'evidence',jsonb_build_object('contractMilestoneAmount',e.contract_milestone_amount,'requiredProgress',e.required_progress,'contractorReportedProgress',e.contractor_reported_progress,'pmVerifiedProgress',e.pm_verified_progress,'pmVerifiedAt',e.pm_verified_at,'scheduleProgress',e.schedule_progress,'boqQuantityProgress',e.boq_quantity_progress,'boqQuantityEvidenceAvailable',e.boq_quantity_evidence_available,'openCriticalIssueCount',e.open_critical_issue_count,'openSnagCount',e.open_snag_count,'pendingVariationCount',e.pending_variation_count,'pendingVariationExposure',e.pending_variation_exposure,'documents',e.documents,'evidenceNote',e.evidence_note,'evidenceReady',e.evidence_ready,'capturedAt',e.captured_at))ORDER BY c.case_number DESC)FROM public.project_payment_certification_cases c JOIN public.project_payment_certification_evidence e ON e.certification_case_id=c.id JOIN public.project_payment_milestones m ON m.id=c.milestone_id JOIN public.project_payment_schedules s ON s.id=m.payment_schedule_id WHERE c.project_id=p_project_id),'[]'::jsonb));END;$$;

CREATE OR REPLACE FUNCTION public.open_payment_certification_evidence(p_milestone_id uuid,p_case_id uuid,p_documents jsonb,p_evidence_note text,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE u uuid:=auth.uid();v_role text;m public.project_payment_milestones%ROWTYPE;s public.project_payment_schedules%ROWTYPE;req public.write_command_requests%ROWTYPE;case_no integer;required numeric;contractor_progress numeric;visit_id bigint;verified numeric;verified_at date;schedule_progress numeric;schedule_critical_count integer:=0;critical_snag_count integer:=0;critical_count integer:=0;snag_count integer:=0;variation_count integer:=0;variation_exposure numeric:=0;ready boolean;result jsonb;
BEGIN SELECT upper(p.role)INTO v_role FROM public.profiles p WHERE p.id=u;SELECT *INTO m FROM public.project_payment_milestones WHERE id=p_milestone_id FOR UPDATE;SELECT *INTO s FROM public.project_payment_schedules WHERE id=m.payment_schedule_id;IF m.id IS NULL THEN RAISE EXCEPTION'PAYMENT_MILESTONE_NOT_FOUND'USING ERRCODE='P0002';END IF;IF u IS NULL OR v_role NOT IN('PM','ADMIN')OR public.can_write_project(m.project_id)IS NOT TRUE THEN RAISE EXCEPTION'PAYMENT_CERTIFICATION_FORBIDDEN'USING ERRCODE='42501';END IF;IF s.status<>'ACTIVE'OR m.status NOT IN('UPCOMING','READY_FOR_REVIEW')OR p_case_id IS NULL OR p_client_request_id IS NULL OR jsonb_typeof(COALESCE(p_documents,'[]'))<>'array'OR char_length(COALESCE(p_evidence_note,''))>3000 THEN RAISE EXCEPTION'INVALID_CERTIFICATION_EVIDENCE_COMMAND'USING ERRCODE='22023';END IF;INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'payment_certification.open',p_client_request_id,m.project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT *INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='payment_certification.open'AND client_request_id=p_client_request_id;IF req.response IS NOT NULL THEN RETURN req.response||jsonb_build_object('idempotentReplay',true);END IF;IF EXISTS(SELECT 1 FROM public.project_payment_certification_cases WHERE milestone_id=m.id)THEN RAISE EXCEPTION'PAYMENT_CERTIFICATION_ALREADY_EXISTS'USING ERRCODE='23505';END IF;SELECT COALESCE(max(case_number),0)+1 INTO case_no FROM public.project_payment_certification_cases WHERE project_id=m.project_id;SELECT sum(percentage)INTO required FROM public.project_payment_milestones WHERE payment_schedule_id=m.payment_schedule_id AND sequence_number<=m.sequence_number;SELECT overall_progress INTO contractor_progress FROM public.contractor_reports WHERE project_id=m.project_id ORDER BY report_date DESC,id DESC LIMIT 1;SELECT id,visit_date INTO visit_id,verified_at FROM public.site_visits WHERE project_id=m.project_id ORDER BY visit_date DESC,id DESC LIMIT 1;SELECT round(avg(observed_progress),2)INTO verified FROM public.site_visit_wps WHERE site_visit_id=visit_id AND observed_progress IS NOT NULL;SELECT round(avg(actual_progress),2)INTO schedule_progress FROM public.project_gantt_tasks WHERE project_id=m.project_id AND COALESCE(is_archived,false)=false AND actual_progress IS NOT NULL;SELECT count(*)INTO schedule_critical_count FROM public.project_gantt_tasks WHERE project_id=m.project_id AND COALESCE(is_archived,false)=false AND(is_critical OR is_blocker)AND status NOT IN('completed','done');SELECT count(*)FILTER(WHERE status NOT IN('CLOSED','CANCELLED')),count(*)FILTER(WHERE priority='CRITICAL'AND status NOT IN('CLOSED','CANCELLED'))INTO snag_count,critical_snag_count FROM public.snags WHERE project_id=m.project_id;critical_count:=schedule_critical_count+critical_snag_count;SELECT count(*),COALESCE(sum(proposed_amount),0)INTO variation_count,variation_exposure FROM public.project_variations WHERE project_id=m.project_id AND status IN('SUBMITTED','UNDER_REVIEW','REVISION_REQUIRED');ready:=verified IS NOT NULL AND verified>=required AND critical_count=0 AND jsonb_array_length(COALESCE(p_documents,'[]'))>0;
INSERT INTO public.project_payment_certification_cases VALUES(p_case_id,m.project_id,m.id,case_no,'UNDER_CERTIFICATION',u,now());INSERT INTO public.project_payment_certification_evidence VALUES(p_case_id,m.project_id,m.id,m.planned_amount,required,contractor_progress,verified,verified_at,schedule_progress,NULL,false,critical_count,snag_count,variation_count,variation_exposure,COALESCE(p_documents,'[]'),btrim(COALESCE(p_evidence_note,'')),ready,u,now());UPDATE public.project_payment_milestones SET status='UNDER_CERTIFICATION'WHERE id=m.id;result:=jsonb_build_object('certificationCaseId',p_case_id,'caseNumber',case_no,'status','UNDER_CERTIFICATION','evidenceReady',ready,'requiredProgress',required,'pmVerifiedProgress',verified,'openCriticalIssueCount',critical_count,'documentCount',jsonb_array_length(COALESCE(p_documents,'[]')));UPDATE public.write_command_requests SET response=result,completed_at=now()WHERE id=req.id;RETURN result||jsonb_build_object('idempotentReplay',false);END;$$;
REVOKE ALL ON FUNCTION private.prevent_payment_evidence_mutation()FROM PUBLIC,anon,authenticated,service_role;REVOKE ALL ON FUNCTION public.get_project_payment_certifications(bigint),public.open_payment_certification_evidence(uuid,uuid,jsonb,text,uuid)FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.get_project_payment_certifications(bigint),public.open_payment_certification_evidence(uuid,uuid,jsonb,text,uuid)TO authenticated;
